items.body:
示例如下:
可以自己根据底图修改项目名称、场景光效、材质配景细节约束等

{
"项目名称": "SU模型转写实摄影 - 清晨禅意山水庭院",
"核心约束": {
"几何保真度": "严格保留原模型建筑结构、山石松树、瀑布水景、步道布局，不改动物体位置与比例。",
"物体完整性": "完整保留建筑、造型松、黑山石、球形灌木、景观设施原始造型，仅替换材质与光影。",
"转换逻辑": "将素模转为高精度PBR写实材质，强化清晨柔和光影、空气薄雾与自然肌理质感，保留东方禅意山水格局。"
},
"场景与光效": {
"设计风格": "现代东方禅意庭院，清晨薄雾氛围，通透空气感，静谧松弛，突出山水、松、石、建筑自然质感。",
"人物": "无人物，空间干净纯粹。",
"建筑立面": "原木格栅立面，细腻哑光木纹，高透低反射玻璃幕墙，映清晨天光绿植倒影，金属连廊顶面柔和漫反射。",
"景观山石": "天然黑山石，风化粗糙花岗岩肌理，覆浅苔藓，被瀑布水汽浸润，湿润哑光带自然水痕。",
"植物水景": "造型黑松针叶鲜活带晨露，枝干纹理自然；球形灌木茂密翠绿，叶片水润有光泽；瀑布水流丝滑通透，溅起细碎水雾，反射清晨柔光。",
"地面步道": "浅灰荔枝面花岗岩，纹理清晰，表面微润，台阶规整，整体质感统一。",
"光影氛围": "清晨日出后1小时，低角度柔和日光（5000K‑5300K），光线穿透枝叶形成丁达尔光效，薄雾弥漫，空气通透清冷，光影斑驳柔和，氛围感静谧治愈。"
},
"摄影参数": {
"相机型号": "索尼A7R5",
"光圈": "f/2.8",
"快门": "1/125s",
"感光度": "ISO 100",
"白平衡": "5200K 清晨冷调日光"
},
"渲染精度": {
"画面表现": "超写实景观摄影，电影级调色，石材粗糙肌理、木材温润质感、植物鲜活细节、水雾空气层次清晰，清晨光影柔和通透，禅意氛围浓厚，完整还原空间布局与写实质感。"
}
}

#aigc #建筑设计 #FLUX2klein #氛围感 #AI生成 #清晨  #AI画图 #自然灵感设计 #景观设计 #园林景观石

